func ptrTransport(p unsafe.Pointer, c int32) any {
	r := (*factoringsubmission.Transport)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (*string)(unsafe.Pointer(&r.FactoringCompanyID))
	case 4:
		return (*string)(unsafe.Pointer(&r.Method))
	case 5:
		return &r.EmailRecipients
	case 6:
		return &r.AttachPackets
	case 7:
		return &r.SftpHost
	case 8:
		return (*int64)(unsafe.Pointer(&r.SftpPort))
	case 9:
		return &r.SftpUsername
	case 10:
		return (*string)(unsafe.Pointer(&r.SftpAuthMethod))
	case 11:
		return &r.SftpSecret
	case 12:
		return &r.SftpKnownHostKey
	case 13:
		return &r.SftpDirectory
	case 14:
		return &r.LastTestedAt
	case 15:
		return &r.LastTestError
	case 16:
		return &r.Version
	case 17:
		return &r.CreatedAt
	case 18:
		return &r.UpdatedAt
	}
	return nil
}

func valueTransport(p unsafe.Pointer, c int32) any {
	r := (*factoringsubmission.Transport)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.FactoringCompanyID)
	case 4:
		return string(r.Method)
	case 5:
		if r.EmailRecipients == nil {
			return nil
		}
		return r.EmailRecipients
	case 6:
		return r.AttachPackets
	case 7:
		if r.SftpHost == "" {
			return nil
		}
		return r.SftpHost
	case 8:
		if r.SftpPort == 0 {
			return nil
		}
		return int64(r.SftpPort)
	case 9:
		if r.SftpUsername == "" {
			return nil
		}
		return r.SftpUsername
	case 10:
		if r.SftpAuthMethod == "" {
			return nil
		}
		return string(r.SftpAuthMethod)
	case 11:
		if r.SftpSecret == "" {
			return nil
		}
		return r.SftpSecret
	case 12:
		if r.SftpKnownHostKey == "" {
			return nil
		}
		return r.SftpKnownHostKey
	case 13:
		if r.SftpDirectory == "" {
			return nil
		}
		return r.SftpDirectory
	case 14:
		if r.LastTestedAt == nil {
			return nil
		}
		return *r.LastTestedAt
	case 15:
		if r.LastTestError == "" {
			return nil
		}
		return r.LastTestError
	case 16:
		return r.Version
	case 17:
		return r.CreatedAt
	case 18:
		return r.UpdatedAt
	}
	return nil
}

